    ],
    "products": [
        {"id": 1, "name": "Flask App", "price": 100}
    ]
}

@app.route('/')
def home():
    return render_template('home.html')

@app.route('/form', methods=['GET', 'POST'])
def process_form():
    name = request.form.get('name')
    email = request.form.get('email')
    phone = request.form.get('phone')

    # Insecurely storing data in memory
    data = {
        "name": name,
        "email": email,
        "phone": phone
    }

    # Simulate SQL injection
    try:
        with app.app_context():
            # Vulnerable SQL injection
            cursor = database['users'].cursor()
            SQL = f"SELECT * FROM users WHERE name = '{name}'"
            cursor.execute(SQL)
            results = cursor.fetchall()
            return render_template('sql_injection.html', results=results)
    except Exception as e:
        return f"Error: {e}"

@app.route('/xss')
def xss():
    # Demonstrate XSS without escaping
    return render_template('xss.html', input=request.args.get('input', "No input"))

@app.route('/idor')
def idor():
    # Insecure direct object reference
    try:
        user = database['users']
        if request.args.get('user_id'):
            user_id = int(request.args.get('user_id'))
            return render_template('idor.html', user=user[user_id])
        return render_template('idor.html')
    except KeyError:
