    {'id': 2, 'name': 'Jane Smith', 'email': 'jane.smith@example.com', 'phone': '555-555-6666'}
]

# Function to sanitize input
def sanitize_input(data):
    return data.replace("'''", "").replace("''", "").replace("--", "").strip()

# Function to check weak password
def is_password_strong(password):
    if len(password) < 8:
        return False
    if not any(char.isupper() for char in password):
        return False
    if not any(char.islower() for char in password):
        return False
    if not any(char.isdigit() for char in password):
        return False
    if not any(char in "!@#$%^&*()_+-= etc" for char in password):
        return False
    return True

# Function to handle form submissions
def handle_form():
    name = sanitize_input(request.form.get('name'))
    email = sanitize_input(request.form.get('email'))
    phone = sanitize_input(request.form.get('phone'))

    if not name or not email or not phone:
        return "All fields are required."

    # Weak password check
    if not is_password_strong(request.form.get('password')):
        return "Password must be at least 8 characters, include uppercase, lowercase, numbers, and special characters."

    # Simulate successful login
