@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form.get('username')
        password = request.form.get('password')
        if username and password:
            if username == 'admin' and password == 'password':
                session['user_id'] = 1
                return redirect(url_for('home'))
        return redirect(url_for('login'))

@app.route('/home')
def home():
    if 'user_id' not in session:
        return redirect(url_for('login'))
    return render_template('home.html')

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        name = request.form.get('name')
        email = request.form.get('email')
        phone = request.form.get('phone')
        password = request.form.get('password')
        if name and email and phone and is_password_strong(password):
            users.append({'id': len(users) + 1, 'name': name, 'email': email, 'phone': phone})
            app.db.commit()
            return "Registration successful!"
        return "Registration failed. Please check the form."
    return render_template('register.html')

@app.route('/logout')
def logout():
    session.pop('user_id', None)
    return redirect(url_for('login'))

# Demonstrating SQL Injection
@app.route('/sqlinj', methods=['GET'])
def sqlinj():
    search_query = request.args.get('q', '').lower()
    # Unsanitized input
    unsafe_query = f"SELECT * FROM users WHERE email LIKE '%{search_query}%'"
    result = db.execute(unsafe_query)
    return render_template('sqlinjection.html', result=unsafe_query)

# Demonstrating XSS
